CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE SEQUENCE seq_adr AS integer START WITH 200 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_avi AS integer START WITH 100 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_car AS integer START WITH 50 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_cli AS integer START WITH 150 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_cmd AS integer START WITH 750 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_msg AS integer START WITH 50 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_pho AS integer START WITH 400 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_pmt AS integer START WITH 150 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_prd AS integer START WITH 100 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE SEQUENCE seq_sga AS integer START WITH 5 INCREMENT BY 1 NO MINVALUE NO MAXVALUE NO CYCLE;

CREATE TABLE t_e_activitepro_act (
    act_idactivitepro integer GENERATED BY DEFAULT AS IDENTITY,
    act_nomactivitepro character varying(64) NOT NULL,
    CONSTRAINT pk_act PRIMARY KEY (act_idactivitepro)
);

CREATE TABLE t_e_client_cli (
    cli_idclient integer NOT NULL DEFAULT (nextval('seq_cli')),
    cli_nomclient character varying(64) NOT NULL,
    cli_prenomclient character varying(64) NOT NULL,
    cli_civiliteclient character(1),
    cli_emailclient character varying(256) NOT NULL,
    cli_telfixeclient character(11),
    cli_telportableclient character(11) NOT NULL,
    cli_datecreationcompte timestamp with time zone NOT NULL DEFAULT (now()),
    cli_hashmdp character(256) NOT NULL,
    cli_pointfideliteclient integer NOT NULL DEFAULT 0,
    cli_newslettermiliboo boolean NOT NULL DEFAULT FALSE,
    cli_newsletterpartenaires boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_cli PRIMARY KEY (cli_idclient)
);

CREATE TABLE t_e_compositionproduit_cmp (
    cmp_idcomposition integer GENERATED BY DEFAULT AS IDENTITY,
