    cmp_prixsoldecomposition numeric(10,2),
    cmp_descriptioncomposition character varying(2048),
    CONSTRAINT pk_cmp PRIMARY KEY (cmp_idcomposition)
);

CREATE TABLE t_e_couleur_cou (
    cou_idcouleur integer GENERATED BY DEFAULT AS IDENTITY,
