    CONSTRAINT pk_cmd PRIMARY KEY (cmd_idcommande),
    CONSTRAINT fk_cmd_adr FOREIGN KEY (cmd_adr_idadresse) REFERENCES t_e_adresse_adr (adr_idadresse) ON DELETE RESTRICT,
    CONSTRAINT fk_cmd_adr2 FOREIGN KEY (cmd_idadresse) REFERENCES t_e_adresse_adr (adr_idadresse) ON DELETE RESTRICT,
    CONSTRAINT fk_cmd_cli FOREIGN KEY (cmd_idclient) REFERENCES t_e_client_cli (cli_idclient) ON DELETE RESTRICT,
    CONSTRAINT fk_cmd_cod FOREIGN KEY (cmd_idcodepromo) REFERENCES t_e_codepromo_cod (cod_idcodepromo) ON DELETE RESTRICT,
    CONSTRAINT fk_cmd_scd FOREIGN KEY (cmd_idstatut) REFERENCES t_e_statutcommande_scd (scd_idstatut) ON DELETE RESTRICT,
    CONSTRAINT fk_cmd_tpt FOREIGN KEY (cmd_idtransporteur) REFERENCES t_e_transporteur_tpt (tpt_idtransporteur) ON DELETE RESTRICT
);

CREATE TABLE t_e_attributproduit_att (
