    pmt_indicepaiement character varying(256),
    CONSTRAINT pk_pmt PRIMARY KEY (pmt_idpaiement),
    CONSTRAINT fk_pmt_car FOREIGN KEY (pmt_idcartebancaire) REFERENCES t_e_cartebancaire_car (car_idcartebancaire) ON DELETE RESTRICT,
    CONSTRAINT fk_pmt_cmd FOREIGN KEY (pmt_idcommande) REFERENCES t_e_commande_cmd (cmd_idcommande) ON DELETE RESTRICT,
    CONSTRAINT fk_pmt_tpm FOREIGN KEY (pmt_idtypepaiement) REFERENCES t_e_typepaiement_tpm (tpm_idtypepaiement) ON DELETE RESTRICT
);

