INSERT INTO t_e_messagechatbot_msg VALUES (1, 34, 'Bonjour, je souhaiterais obtenir de l''aide pour ma commande', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. En quoi puis-je vous aider ?');
INSERT INTO t_e_messagechatbot_msg VALUES (2, 4, 'Bonsoir c''est quoi votre meilleur canapé ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Je vous invite à consulter nos nouveautés pour découvrir les dernières tendances !');
INSERT INTO t_e_messagechatbot_msg VALUES (3, 34, 'Je souhaiterais avoir plus d''informations sur les modalités de liTRUEson', 'Vous avez à votre disposition la liTRUEson express ou la liTRUEson sous 2 à 5 jours ouvrables. Le transporteur pour la liTRUEson express est France Express.');
INSERT INTO t_e_messagechatbot_msg VALUES (4, 6, 'Sa marche vrmt votre truc ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. En quoi puis-je vous aider ?');
INSERT INTO t_e_messagechatbot_msg VALUES (5, 8, '1 2 1 2 Test', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Je suis prêt à répondre à vos questions ! :)');
INSERT INTO t_e_messagechatbot_msg VALUES (6, 45, 'Je souhaite vendre des meubles', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Si vous souhaitez devenir un de nos partenaires, je vous invite à nous contacter par mail à l''adresse partenaire@miliboo.fr');
INSERT INTO t_e_messagechatbot_msg VALUES (7, 29, 'Bonsoir je cherche une nouvelle table basse', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients.  Cherchez-vous un modèle en particulier ?');
INSERT INTO t_e_messagechatbot_msg VALUES (8, 34, 'Merci, dois-je être présent à la réception ?', 'Votre signature sera nécessaire, votre présence sera donc requise. Avez-vous d''autres questions ?');
INSERT INTO t_e_messagechatbot_msg VALUES (9, 12, 'Comment faire pour commander ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Pour cela il vous suffit de créer un compte client. Vos produits déjà ajoutées au panier seront alors disponibles à la commande.');
INSERT INTO t_e_messagechatbot_msg VALUES (10, 34, 'Comment faire si je suis absent ?', 'En cas d''absence, votre commande sera stockée dans un entrepot du transporteur, en attentes de nouvelles modalités de liTRUEson. Le transporteur prendra contact avec vous afin de les établir.');
INSERT INTO t_e_messagechatbot_msg VALUES (11, 42, 'Bonjour le produit que je voulais n''est plus disponible !!!', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Ce produit étant en rupture de stock, il n''est pas possible de le commander pour l''instant. Nous vous présentons nos excuses pour la gêne occasionée.');
INSERT INTO t_e_messagechatbot_msg VALUES (12, 37, 'Bonsoir je cherche une nouvelle TV', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Malhereusement, nous ne disposons pas de téléviseur sur notre site. Avez-vous d''autres demandes ?');
INSERT INTO t_e_messagechatbot_msg VALUES (13, 50, 'Bonjour où se trouve mon panier ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Il se trouve dans le coin droit de notre page web. Il vous suffit de cliquer sur l''icône "Panier" pour l''afficher.');
INSERT INTO t_e_messagechatbot_msg VALUES (14, 10, 'Le chatbot fonctionne ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. En quoi puis-je vous aider ?');
INSERT INTO t_e_messagechatbot_msg VALUES (15, 34, 'Merci !', 'Je suis ravi d''avoir pu vous aider. Avez-vous d''autres questions ?');
INSERT INTO t_e_messagechatbot_msg VALUES (16, 12, 'Bonjour je veux supprimer mon compte svp', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Sans problème ! Il vous suffit d''envoyer un mail à l''adresse support-client@miliboo.fr afin de formuler votre demande. Un de nos conseiller vous répondrera sous 48H.');
INSERT INTO t_e_messagechatbot_msg VALUES (17, 21, 'Bonjour c''est ChatGpt ?', 'Bienvenue sur le chatbot support Miliboo, notre conversation sera enregistrée afin de mieux répondre aux besoins clients. Je ne suis perfectionné à ce point, mais je souhaite faire de mon mieux pour vous aider ! Comment puis-je répondre à vos questions ?');
INSERT INTO t_e_messagechatbot_msg VALUES (18, 50, 'Merci c''est bon', 'Avec plaisir ! Avez-vous d''autres questions ?');
